import 'package:flutter/material.dart';import 'package:flutter_bloc/flutter_bloc.dart';import 'package:zan/Features/Global/Authentication/domain/repository/authentication_repo_impl.dart';import 'package:zan/Features/Global/Authentication/presentation/Controller/authentication_cubit.dart';import '../../../../../Core/Resources/app_list.dart';import '../Controller/AnimatedCrossFade/animated_cross_fade_cubit.dart';import 'container_authentication_body.dart';class AuthenticationBody extends StatelessWidget {  const AuthenticationBody({    super.key,  });  @override  Widget build(BuildContext context) {    return Scaffold(        body: Stack(      clipBehavior: Clip.none,      children: [        ...AppList.gradientColorsBackground,        MultiBlocProvider(          providers: [            BlocProvider(              create: (context) => AnimatedCrossFadeCubit(),            ),            BlocProvider(              create: (context) => AuthenticationCubit(                AuthenticationRepoImpl(),              ),            ),          ],          child: ContainerAuthenticationBody(),        ),      ],    ));  }}